const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pic=(id)=>`https://images.unsplash.com/${id}?auto=format&fit=crop&w=800&q=85`;
function initial(){return {users:[{id:1,name:'田中 はるか',room:'203',points:120,consent:true,face:'https://i.pravatar.cc/100?img=47'},{id:2,name:'佐藤 まこと',room:'105',points:80,consent:true,face:'https://i.pravatar.cc/100?img=12'},{id:3,name:'鈴木 ゆうこ',room:'302',points:150,consent:true,face:'https://i.pravatar.cc/100?img=44'},{id:4,name:'山本 あきら',room:'401',points:60,consent:false,face:''}],products:[{id:1,name:'毎日にちょうどいい、白いマグ',points:30,seller:2,category:'暮らし',image:pic('photo-1514228742587-6b1558fcca3d'),description:'手になじむ陶器のマグカップです。来客用として使っていました。目立つ傷や欠けはありません。',condition:'目立つ傷なし'},{id:2,name:'お出かけにも。小さなリュック',points:60,seller:3,category:'衣類・バッグ',image:pic('photo-1553062407-98eeb64c6a62'),description:'軽くて使いやすいリュック。日常のお出かけ用に。スタッフが外観を確認しました。',condition:'使用感あり'},{id:3,name:'週末をたのしむ、読みものセット',points:20,seller:4,category:'本・あそび',image:pic('photo-1495446815901-a7297e633e8d'),description:'読み終えた本のセットです。ページの折れが少しあります。次に読む方へ。',condition:'使用感あり'},{id:4,name:'食卓を彩る、うつわのセット',points:50,seller:3,category:'暮らし',image:pic('photo-1490312278390-ab64016e0aa9'),description:'小鉢とお皿のセットです。会場で実物の状態をご確認ください。',condition:'目立つ傷なし'},{id:5,name:'窓辺におきたい、グリーン',points:40,seller:2,category:'暮らし',image:pic('photo-1416879595882-3373a0480b5b'),description:'大切に育てた鉢植えです。明るい室内で育てていました。',condition:'良好'},{id:6,name:'親子で読もう、絵本のセット',points:30,seller:1,category:'本・あそび',image:pic('photo-1507842217343-583bb7270b66'),description:'お子さんとの読み聞かせに。書き込みはありません。',condition:'使用感あり'}],notices:[],logs:[]}}
let state;try{state=JSON.parse(localStorage.getItem('meguru-v1'))||initial()}catch{state=initial()}let uid=1,page='market',filter='すべて',query='';const me=()=>state.users.find(u=>u.id===uid),user=id=>state.users.find(u=>u.id===id);function save(){localStorage.setItem('meguru-v1',JSON.stringify(state))}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function avatar(u){return u.consent&&u.face?`<img class="avatar" src="${esc(u.face)}" alt="${esc(u.name)}さんの顔写真（架空）">`:'<span class="avatar" aria-label="顔写真非公開">◯</span>'}function seller(u){return `${avatar(u)}<span>${esc(u.name)} さん<br><small class="muted">${u.consent?'顔写真の掲載に同意済み':'顔写真は非公開'}</small></span>`}
$('#user').innerHTML=state.users.map(u=>`<option value="${u.id}">${esc(u.name)} さん</option>`).join('');$('#user').onchange=e=>{uid=+e.target.value;render()};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});$('#reset').onclick=()=>{if(confirm('交換・登録・ポイント編集をすべて初期状態に戻しますか？')){state=initial();save();render();toast('デモを初期状態に戻しました')}};
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#badge').textContent=state.notices.filter(n=>n.to===uid&&!n.read).length||'';if(page==='market')market();else if(page==='notices')notices();else staff()}
function options(){return state.users.map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}function readFile(f){return new Promise((resolve,reject)=>{if(!f||!f.type.startsWith('image/'))return reject(Error('画像ファイルを選択してください'));if(f.size>1500000)return reject(Error('画像は1.5MB以下を選んでください'));let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('画像を読み込めませんでした'));r.readAsDataURL(f)})}

